import{_ as t,o as a,c as o,a1 as i}from"./chunks/framework.CiMD_7j0.js";const h=JSON.parse('{"title":"Security & Permissions","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"30db939c-1f82-4d84-82bd-709b30295e26","PropagateID":"30db939c-1f82-4d84-82bd-709b30295e26","ReservedCode1":"61f552d5-dd1f-4dda-9282-719a8a2e67bc","ReservedCode2":"61f552d5-dd1f-4dda-9282-719a8a2e67bc"}},"headers":[],"relativePath":"en/guide/python/security.md","filePath":"en/guide/python/security.md","lastUpdated":null}'),r={name:"en/guide/python/security.md"};function n(d,e,s,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="security-permissions" tabindex="-1">Security &amp; Permissions <a class="header-anchor" href="#security-permissions" aria-label="Permalink to &quot;Security &amp; Permissions&quot;">​</a></h1><h2 id="four-layer-permission-model" tabindex="-1">Four-Layer Permission Model <a class="header-anchor" href="#four-layer-permission-model" aria-label="Permalink to &quot;Four-Layer Permission Model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Typical scenario</th><th>Implementation</th></tr></thead><tbody><tr><td>No login</td><td>Website home, marketplace list</td><td>No auth dependency injected</td></tr><tr><td>Login required</td><td>Profile, my orders</td><td><code>Depends(get_current_user)</code></td></tr><tr><td>Rule-based auth</td><td>User, role, plugin management</td><td><code>require_permission(&quot;...&quot;)</code></td></tr><tr><td>Data scope</td><td>Access only own plugins or data</td><td>Service layer filters by <code>user_id</code></td></tr></tbody></table><p>The frontend <code>v-permission</code> directive only hides buttons — it cannot replace backend permission checks. Plugin admin APIs must re-validate permissions and resource ownership on the server.</p><h2 id="key-storage" tabindex="-1">Key Storage <a class="header-anchor" href="#key-storage" aria-label="Permalink to &quot;Key Storage&quot;">​</a></h2><p>SMTP authorization codes, DeepSeek API keys and LemPay merchant keys are stored using ApeAdmin&#39;s core encryption capability. Admin APIs only return a &quot;configured&quot; status, never the plaintext. In production, write keys through controlled configuration; never put keys inside plugin ZIPs, logs, Markdown docs or frontend code.</p><h2 id="uploaded-package-checks" tabindex="-1">Uploaded Package Checks <a class="header-anchor" href="#uploaded-package-checks" aria-label="Permalink to &quot;Uploaded Package Checks&quot;">​</a></h2><p>Plugin ZIPs are not extracted into the running directory during analysis, and Python/JavaScript inside them is never executed. The platform checks:</p><ul><li>Path traversal, absolute paths and symbolic links</li><li>Encrypted files, file count, total extracted size and abnormal compression ratios</li><li>Required <code>plugin.json</code> fields and version consistency</li><li>Dynamic code execution, system commands, outbound network requests and suspected hard-coded keys</li></ul><p>Static checks and AI analysis only provide review-support information; the final go-live decision must be made by an admin after review and publishing.</p><h2 id="website-content" tabindex="-1">Website Content <a class="header-anchor" href="#website-content" aria-label="Permalink to &quot;Website Content&quot;">​</a></h2><p>Navigation links only allow controlled in-site paths or explicitly permitted HTTPS addresses. User-submitted Markdown, images, demo links and plugin docs must pass format validation and HTML sanitization before being shown publicly.</p>',12)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
